import { Button, IconButton, cn, useI18n } from '@gntik-ai/ui';
import { ArrowUp, FileText, Paperclip, Square, X } from 'lucide-react';
import { useId, useRef, useState, type ChangeEvent, type FormEvent, type KeyboardEvent, type ReactNode, type Ref } from 'react';
import { formatBytes } from '../utils/format';
import { chatComposerStyles as s } from './chatComposer.variants';

export interface ComposerAttachment {
  id: string;
  name: string;
  /** Size in bytes. */
  size?: number;
}

export interface ChatComposerProps {
  /** Controlled text. Pair with `onValueChange`. */
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Called with the trimmed text when the user sends. Uncontrolled composers clear themselves. */
  onSubmit: (text: string, attachments: ComposerAttachment[]) => void;
  /** A reply is streaming: Send turns into Stop, Enter no longer sends, Escape stops. */
  streaming?: boolean;
  onStop?: () => void;
  disabled?: boolean;
  placeholder?: string;
  /** Accessible name of the text box. */
  label?: string;
  /** Soft limit: shows a counter near the limit and blocks sending above it. */
  maxLength?: number;
  /** Attached files shown as removable chips. */
  attachments?: ComposerAttachment[];
  /** Shows the attach button; called with the files the user picked. */
  onAttach?: (files: File[]) => void;
  onRemoveAttachment?: (id: string) => void;
  /** `accept` for the file picker (e.g. ".pdf,.csv,image/*"). */
  accept?: string;
  /** Slot left of the send button, e.g. a model Select. */
  modelPicker?: ReactNode;
  /** Extra tools after the attach button. */
  tools?: ReactNode;
  /** Small line under the box. Defaults to the keyboard hint; pass null to hide it. */
  hint?: ReactNode;
  className?: string;
  ref?: Ref<HTMLTextAreaElement>;
}

/**
 * Message box for a chat: grows with its content, Enter sends and Shift+Enter adds a line,
 * files show as removable chips, a model picker can sit in the toolbar, and while a reply
 * streams the send button becomes Stop (Escape also stops).
 */
export function ChatComposer({
  value,
  defaultValue = '',
  onValueChange,
  onSubmit,
  streaming = false,
  onStop,
  disabled = false,
  placeholder: placeholderProp,
  label: labelProp,
  maxLength,
  attachments = [],
  onAttach,
  onRemoveAttachment,
  accept,
  modelPicker,
  tools,
  hint,
  className,
  ref,
}: ChatComposerProps) {
  const { t } = useI18n();
  const placeholder = placeholderProp ?? t('chat.placeholder');
  const label = labelProp ?? t('chat.messageLabel');
  const id = useId();
  const [inner, setInner] = useState(defaultValue);
  const text = value ?? inner;
  const fileInput = useRef<HTMLInputElement>(null);

  const setText = (next: string) => {
    if (value === undefined) setInner(next);
    onValueChange?.(next);
  };

  const length = text.length;
  const over = maxLength !== undefined && length > maxLength;
  const showCount = maxLength !== undefined && length >= maxLength * 0.8;
  const canSend = !disabled && !streaming && !over && (text.trim().length > 0 || attachments.length > 0);

  const send = () => {
    if (!canSend) return;
    onSubmit(text.trim(), attachments);
    if (value === undefined) setInner('');
  };

  const onKeyDown = (e: KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
      e.preventDefault();
      send();
    } else if (e.key === 'Escape' && streaming && onStop) {
      e.preventDefault();
      onStop();
    }
  };

  const onFiles = (e: ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files ?? []);
    if (files.length) onAttach?.(files);
    e.target.value = '';
  };

  const hintNode =
    hint === undefined ? (
      <>
        <kbd className="font-sans">{t('kbd.enter')}</kbd> {t('chat.hintSend')} · <kbd className="font-sans">{t('chat.shiftEnter')}</kbd> {t('chat.hintNewLine')}
      </>
    ) : (
      hint
    );

  return (
    <div className={className}>
      <form
        className={s.root}
        data-disabled={disabled || undefined}
        onSubmit={(e: FormEvent) => {
          e.preventDefault();
          send();
        }}
      >
        {attachments.length > 0 && (
          <ul aria-label={t('chat.attachments')} className={s.attachments}>
            {attachments.map((a) => (
              <li key={a.id} className={s.chip}>
                <FileText size={13} aria-hidden className="shrink-0 text-muted-foreground" />
                <span className={s.chipName} title={a.name}>
                  {a.name}
                </span>
                {a.size !== undefined && <span className={s.chipSize}>{formatBytes(a.size)}</span>}
                {onRemoveAttachment && (
                  <button
                    type="button"
                    className={s.chipRemove}
                    aria-label={t('common.removeItem', { label: a.name })}
                    disabled={disabled}
                    onClick={() => onRemoveAttachment(a.id)}
                  >
                    <X size={12} aria-hidden />
                  </button>
                )}
              </li>
            ))}
          </ul>
        )}
        <textarea
          ref={ref}
          id={`${id}-input`}
          rows={1}
          value={text}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={onKeyDown}
          disabled={disabled}
          placeholder={placeholder}
          aria-label={label}
          aria-invalid={over || undefined}
          aria-describedby={showCount ? `${id}-count` : undefined}
          className={s.textarea}
        />
        <div className={s.toolbar}>
          <div className={s.tools}>
            {onAttach && (
              <>
                <IconButton size="sm" icon={Paperclip} label={t('chat.attach')} disabled={disabled} onClick={() => fileInput.current?.click()} />
                <input ref={fileInput} type="file" multiple hidden accept={accept} aria-label={t('chat.attach')} onChange={onFiles} />
              </>
            )}
            {tools}
          </div>
          <div className={s.end}>
            {showCount && (
              <span id={`${id}-count`} className={cn(s.count, over && s.countOver)}>
                {length}/{maxLength}
                {over && <span className="sr-only"> {t('chat.overLimit')}</span>}
              </span>
            )}
            {modelPicker}
            {streaming ? (
              <Button size="sm" variant="secondary" icon={Square} aria-label={t('chat.stop')} onClick={onStop} disabled={!onStop}>
                {t('common.stop')}
              </Button>
            ) : (
              <IconButton size="sm" variant="primary" icon={ArrowUp} label={t('chat.send')} type="submit" disabled={!canSend} />
            )}
          </div>
        </div>
      </form>
      {hintNode !== null && <p className={s.hint}>{hintNode}</p>}
    </div>
  );
}

import { focusRing } from '../utils/focus';

/** Slot classes for ChatComposer (focus ring on the frame, like the legacy composer). */
export const chatComposerStyles = {
  root: [
    'overflow-hidden rounded-xl border border-border bg-card shadow-sm transition-colors motion-reduce:transition-none',
    'focus-within:border-primary/60 focus-within:ring-2 focus-within:ring-ring/25',
    'data-[disabled]:opacity-60',
  ].join(' '),
  attachments: 'flex flex-wrap gap-1.5 px-3 pt-3',
  chip: 'inline-flex h-7 max-w-60 items-center gap-1.5 rounded-md border border-border bg-secondary/50 ps-2 pe-1 text-[12px] text-foreground',
  chipName: 'truncate font-medium',
  chipSize: 'shrink-0 font-mono text-[10.5px] text-muted-foreground',
  chipRemove: `grid size-5 shrink-0 place-items-center rounded text-muted-foreground hover:bg-foreground/10 hover:text-foreground ${focusRing}`,
  textarea: [
    'block max-h-[220px] min-h-[52px] w-full resize-none bg-transparent px-3.5 py-3 text-[14px] leading-6 text-foreground',
    'field-sizing-content placeholder:text-muted-foreground focus:outline-none disabled:cursor-not-allowed',
  ].join(' '),
  toolbar: 'flex items-center justify-between gap-2 px-2 pb-2',
  tools: 'flex min-w-0 items-center gap-1',
  end: 'flex shrink-0 items-center gap-2',
  count: 'font-mono text-[11px] text-muted-foreground tabular-nums',
  countOver: 'text-destructive-text',
  hint: 'mt-1.5 px-1 text-center text-[11.5px] text-muted-foreground',
} as const;

export { ChatComposer, type ChatComposerProps, type ComposerAttachment } from './ChatComposer';
export { chatComposerStyles } from './chatComposer.variants';
export { doc as chatComposerDoc } from './ChatComposer.doc';

/** "840 ms" below a second, "2.4 s" below a minute, "1 m 05 s" above. */
export function formatDuration(ms: number) {
  if (ms < 1000) return `${Math.round(ms)} ms`;
  if (ms < 60_000) return `${(ms / 1000).toFixed(1)} s`;
  const m = Math.floor(ms / 60_000);
  const s = Math.round((ms % 60_000) / 1000);
  return `${m} m ${String(s).padStart(2, '0')} s`;
}

/** "12 KB", "3.4 MB". */
export function formatBytes(bytes: number) {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

/** Short local time ("14:05") for a message timestamp. */
export function formatTime(date: Date) {
  return date.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' });
}

/** Pretty-prints any value as JSON; falls back to String() for cyclic or exotic values. */
export function toJson(value: unknown) {
  if (typeof value === 'string') return value;
  try {
    return JSON.stringify(value, null, 2) ?? String(value);
  } catch {
    return String(value);
  }
}

import type { ComponentDoc } from '@gntik-ai/ui';

export const doc: ComponentDoc = {
  name: 'ChatComposer',
  group: 'Forms',
  status: 'beta',
  description:
    'Chat input: autosizing textarea, Enter sends and Shift+Enter adds a line, removable attachment chips, a model-picker slot, a character counter near the limit, a disabled state, and a Stop button while a reply streams.',
  keyboard: [
    ['Enter', 'Sends the message (ignored while streaming or during IME composition)'],
    ['Shift+Enter', 'Inserts a new line'],
    ['Escape', 'While a reply streams: stops it'],
    ['Tab', 'Moves from the text box to attachment remove buttons, tools, the model picker and Send/Stop'],
  ],
  tokens: ['card', 'border', 'primary', 'ring', 'secondary', 'muted-foreground', 'destructive-text', 'focus-ring'],
};
